typedef ZSTD_inBuffer = ZSTD_inBuffer_s;

/// Streaming
final class ZSTD_inBuffer_s extends ffi.Struct {
  /// < start of input buffer
  external ffi.Pointer<ffi.Void> src;

  /// < size of input buffer
  @ffi.Size()
  external int size;

  /// < position where reading stopped. Will be updated. Necessarily 0 <= pos <= size
  @ffi.Size()
  external int pos;

  static ffi.Pointer<ZSTD_inBuffer_s> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Void> src,
    required int size,
    required int pos,
  }) => $allocator<ZSTD_inBuffer_s>()
    ..ref.src = src
    ..ref.size = size
    ..ref.pos = pos;
}

typedef ZSTD_outBuffer = ZSTD_outBuffer_s;

final class ZSTD_outBuffer_s extends ffi.Struct {
  /// < start of output buffer
