  /// < position where writing stopped. Will be updated. Necessarily 0 <= pos <= size
  @ffi.Size()
  external int pos;

  static ffi.Pointer<ZSTD_outBuffer_s> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Void> dst,
